module carry_adder #(
  parameter int WIDTH = 8
) (
  input  logic [WIDTH-1:0] a,
  input  logic [WIDTH-1:0] b,
  input  logic             cin,
  output logic [WIDTH-1:0] sum,
  output logic             cout
);
  assign {cout, sum} = {1'b0, a} + {1'b0, b} + {{WIDTH{1'b0}}, cin};
endmodule

counter-mod-n.code:
module counter_mod_n #(
  parameter int N = 10
) (
  input  logic                 clk,
  input  logic                 rst,
  input  logic                 en,
  output logic [$clog2(N)-1:0] count,
  output logic                 wrap
);
  localparam int W = $clog2(N);
  localparam logic [W-1:0] LAST = W'(N - 1);

  assign wrap = en && count == LAST;

  always_ff @(posedge clk)
    if (rst) count <= '0;
    else if (wrap) count <= '0;
    else if (en) count <= count + 1'b1;
endmodule

mux4.code:
module mux4 #(
  parameter int WIDTH = 8
) (
  input  logic [1:0]       sel,
  input  logic [WIDTH-1:0] d0,
  input  logic [WIDTH-1:0] d1,
  input  logic [WIDTH-1:0] d2,
  input  logic [WIDTH-1:0] d3,
  output logic [WIDTH-1:0] y
);
  always_comb begin
    unique case (sel)
      2'd0: y = d0;
      2'd1: y = d1;
      2'd2: y = d2;
      2'd3: y = d3;
    endcase
  end
endmodule

seq-detector.code:
module seq_detector (
  input  logic clk,
  input  logic rst,
  input  logic din,
  output logic found
);
  // State: the longest suffix of the received bits that is a prefix of 1011.
  typedef enum logic [1:0] {S_NONE, S_1, S_10, S_101} state_t;
  state_t state, next;

  always_comb begin
    unique case (state)
      S_NONE: next = din ? S_1 : S_NONE;
      S_1:    next = din ? S_1 : S_10;
      S_10:   next = din ? S_101 : S_NONE;
      S_101:  next = din ? S_1 : S_10;  // 1011 ends in "1"; 1010 ends in "10"
    endcase
  end

  always_ff @(posedge clk)
    if (rst) begin
      state <= S_NONE;
      found <= 1'b0;
    end else begin
      state <= next;
      found <= state == S_101 && din;
    end
endmodule

sync-fifo.code:
module sync_fifo #(
  parameter int WIDTH = 8,
  parameter int DEPTH = 16
) (
  input  logic             clk,
  input  logic             rst_n,
  input  logic             push,
  input  logic [WIDTH-1:0] wdata,
  input  logic             pop,
  output logic [WIDTH-1:0] rdata,
  output logic             full,
  output logic             empty
);
  localparam int AW = $clog2(DEPTH);

  logic [WIDTH-1:0] mem [DEPTH];
  logic [AW-1:0] wptr, rptr;
  logic [AW:0] count;

  wire do_push = push && !full;
  wire do_pop = pop && !empty;

  assign full = count == (AW + 1)'(DEPTH);
  assign empty = count == '0;
  assign rdata = mem[rptr];

  always_ff @(posedge clk) begin
    if (do_push) mem[wptr] <= wdata;
    if (!rst_n) begin
      wptr <= '0;
      rptr <= '0;
      count <= '0;
    end else begin
      if (do_push) wptr <= wptr + 1'b1;
      if (do_pop) rptr <= rptr + 1'b1;
      count <= count + (AW + 1)'(do_push) - (AW + 1)'(do_pop);
    end
  end
endmodule
